//! The emitter byte gate: every byte the backend emits for a fixed set of
//! programs, pinned.
//!
//! The differential suites say an emitted module *behaves* like the
//! interpreter. They are blind to a change that moves bytes and keeps
//! behaviour. A refactor of the emitter that promises "the generated bytes do
//! not change" needs a test that fails when they do, on more than a handful
//! of opcodes; this is that test.
//!
//! **Programs.** Every fixture under `tests/compile-pass` (the
//! enumeration of `standalone_wasm_census.rs`) and `tests/regression` that
//! the front end accepts, and every cell of the typed matrix
//! (`typed_matrix/cells.rs`, the tables `typed_matrix.rs` runs) that the
//! front end accepts.
//! Two separately named fixed-color variants keep native instruction coverage
//! for fixtures whose color inputs require interpreter-hosted execution;
//! the complete original fixtures remain pinned independently.
//!
//! **Tiers.** Each program is built three ways:
//!
//! | Tier | Entry point | Outcome |
//! |---|---|---|
//! | `chart` | [`compile_program_to_wasm`] | `native`, or `hosted:<kind>` when native lowering refuses with `<kind>` and the interpreter-hosted wrapper is emitted |
//! | `strategy` | [`compile_standalone_wasm_program`], strategy module type | `ok`, or `refused:<kind>` |
//! | `indicator` | the same, indicator module type; skipped for a `strategy()` source, which can never be an indicator module | `ok`, or `refused:<kind>` |
//!
//! A fixture is built with the default signal designation. A matrix cell's
//! strategy module is built with its "Backtest Signal" plot designated, as
//! `typed_matrix.rs` builds it. An indicator module designates no plot.
//!
//! **What is pinned** (`emitter_byte_gate/manifest.rs`). For every module:
//! the SHA-256 of the whole module, the number of function bodies in its code
//! section, and a digest of them (the SHA-256 of each body's length and
//! SHA-256, in order). For fixtures the two hashes are written in full, and
//! every function body's own length and hash (its first 64 bits) is pinned
//! too, so a change names the function. For matrix cells, which outnumber the
//! fixtures a hundred to one, the two hashes are truncated to 48 bits and the
//! per-function hashes are not stored: a change names the program and the
//! tier and says whether the code section or something outside it moved. A
//! pinned hash is only ever compared with the new hash of the same thing, so
//! a prefix is enough to see a change.
//!
//! A function index is the body's position in the code section, so imported
//! functions are not counted.
//!
//! **The inventory.** The same file pins, per `CsilInstr` variant and per
//! `PureFunc` of a `CallPure`, how many programs with at least one natively
//! lowered module contain it, and which variants no such program contains.
//! It is read off the compiled `CsilProgram`s; no production code is
//! instrumented. The variant lists are read from the enum definitions in the
//! `pinewasm_csil` and `pinewasm_hir` sources, so a new variant appears in the
//! inventory without an edit here.
//!
//! ```text
//! cargo test -p pinewasm_aot --test emitter_byte_gate -- --nocapture
//! EMITTER_BYTE_GATE_BLESS=1 cargo test -p pinewasm_aot --test emitter_byte_gate   # rewrite the manifest
//! ```
//!
//! A failure separates three things: modules whose **bytes changed**, programs
//! **newly accepted or refused** by a tier, and programs added to or removed
//! from the set. Only the first is forbidden to a byte-preserving refactor.

use pinewasm_aot::{
    compile_program_to_wasm, compile_standalone_wasm_program, ExecutionMode,
    StandaloneWasmModuleType, StandaloneWasmOptions,
};
use pinewasm_compiler::{compile, CompileOptions};
use pinewasm_csil::{CsilInstr, CsilProgram};
use sha2::{Digest, Sha256};
use std::collections::{BTreeMap, BTreeSet, HashMap};
use std::fmt::Write as _;
use std::path::{Path, PathBuf};
use std::sync::OnceLock;

/// The typed matrix's tables and enumeration.
#[path = "typed_matrix/cells.rs"]
mod matrix;

/// The pinned manifest, as a Rust source file so the test crate compiles it
/// directly.
#[path = "emitter_byte_gate/manifest.rs"]
mod manifest;

type Hash = [u8; 32];

fn sha256(bytes: &[u8]) -> Hash {
    Sha256::digest(bytes).into()
}

fn hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        let _ = write!(out, "{byte:02x}");
    }
    out
}

// ---------------------------------------------------------------------------
// The programs.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Family {
    Fixture,
    Matrix,
}

struct Program {
    /// `fixture:<directory>/<file>` or `matrix:<cell id>`.
    id: String,
    family: Family,
    source: String,
}

/// The fixture directories, relative to this crate.
const FIXTURE_ROOT: &str = "../../tests";
const FIXTURE_DIRECTORIES: &[&str] = &["compile-pass", "regression"];

fn collect_pine_files(dir: &Path, out: &mut Vec<PathBuf>) {
    for entry in std::fs::read_dir(dir).expect("readable fixture directory") {
        let path = entry.expect("directory entry").path();
        if path.is_dir() {
            if path
                .file_name()
                .is_some_and(|name| name == "generated_failures")
            {
                continue;
            }
            collect_pine_files(&path, out);
        } else if path
            .extension()
            .is_some_and(|extension| extension == "pine")
        {
            out.push(path);
        }
    }
}

/// Every program the gate builds, fixtures first, in a fixed order.
fn programs() -> Vec<Program> {
    let root = Path::new(FIXTURE_ROOT);
    let mut out = Vec::new();
    for directory in FIXTURE_DIRECTORIES {
        let mut files = Vec::new();
        collect_pine_files(&root.join(directory), &mut files);
        files.sort();
        for path in files {
            let relative = path
                .strip_prefix(root)
                .expect("under the fixture root")
                .components()
                .map(|part| part.as_os_str().to_string_lossy())
                .collect::<Vec<_>>()
                .join("/");
            let source = std::fs::read_to_string(&path)
                .unwrap_or_else(|error| panic!("{}: {error}", path.display()));
            // Keep the input-color admission boundary and the native byte
            // coverage that accompanies it as separate, explicit programs.
            let replacements: &[(&str, &str)] = match relative.as_str() {
                "compile-pass/inputs.pine" => &[(
                    "tint = input.color(#2196F3, \"Tint\")",
                    "tint = #2196F3",
                )],
                "regression/language-strategy.pine" => &[
                    ("strategy_request_input_tint = input.color(color.new(color.blue, 90), \"Tint\", group = \"Text\")", "strategy_request_input_tint = color.new(color.blue, 90)"),
                    ("strategy_request_input_gcol = input(color.red, \"Generic Color\", group = \"Generic\")", "strategy_request_input_gcol = color.red"),
                ],
                _ => &[],
            };
            if !replacements.is_empty() {
                let mut fixed = source.clone();
                for (input, default) in replacements {
                    assert_eq!(fixed.matches(input).count(), 1, "{relative}: {input}");
                    fixed = fixed.replace(input, default);
                }
                out.push(Program {
                    id: format!("fixture:fixed-color-control/{relative}"),
                    family: Family::Fixture,
                    source: fixed,
                });
            }
            out.push(Program {
                id: format!("fixture:{relative}"),
                family: Family::Fixture,
                source,
            });
        }
    }
    for cell in matrix::cells() {
        out.push(Program {
            id: format!("matrix:{}", cell.id),
            family: Family::Matrix,
            source: cell.program,
        });
    }
    out
}

// ---------------------------------------------------------------------------
// One module.

/// One function body of a code section: its length in bytes and its hash.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Body {
    length: usize,
    hash: Hash,
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct Module {
    hash: Hash,
    bodies: Vec<Body>,
}

impl Module {
    /// The digest of the function bodies: the hash of every body's length and
    /// hash, in code-section order.
    fn bodies_digest(&self) -> Hash {
        let mut hasher = Sha256::new();
        for body in &self.bodies {
            hasher.update((body.length as u64).to_le_bytes());
            hasher.update(body.hash);
        }
        hasher.finalize().into()
    }
}

/// Hashes of function bodies already seen. Every module carries the same
/// spliced runtime functions, so nearly every body is a repeat.
type BodyCache = HashMap<Vec<u8>, Hash>;

/// The byte range of every function body in the code section, in order.
fn body_ranges(wasm: &[u8]) -> Vec<std::ops::Range<usize>> {
    wasmparser::Parser::new(0)
        .parse_all(wasm)
        .filter_map(|payload| match payload.expect("an emitted module parses") {
            wasmparser::Payload::CodeSectionEntry(body) => {
                let range = body.range();
                Some(range.start as usize..range.end as usize)
            }
            _ => None,
        })
        .collect()
}

fn fingerprint(wasm: &[u8], cache: &mut BodyCache) -> Module {
    let mut bodies = Vec::new();
    for range in body_ranges(wasm) {
        let bytes = &wasm[range];
        let hash = match cache.get(bytes) {
            Some(hash) => *hash,
            None => {
                let hash = sha256(bytes);
                cache.insert(bytes.to_vec(), hash);
                hash
            }
        };
        bodies.push(Body {
            length: bytes.len(),
            hash,
        });
    }
    Module {
        hash: sha256(wasm),
        bodies,
    }
}

// ---------------------------------------------------------------------------
// One program.

const TIERS: [&str; 3] = ["chart", "strategy", "indicator"];

/// What one tier did with one program.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Emit {
    /// A module, and how it was reached: `native`, `hosted:<kind>` or `ok`.
    Module { how: String, module: Module },
    /// No module: `refused:<kind>`.
    Refused(String),
}

impl Emit {
    fn state(&self) -> &str {
        match self {
            Emit::Module { how, .. } => how,
            Emit::Refused(state) => state,
        }
    }

    /// Whether this tier lowered the program's instructions to WebAssembly.
    fn is_native(&self) -> bool {
        matches!(self, Emit::Module { how, .. } if !how.starts_with("hosted:"))
    }
}

struct Record {
    id: String,
    family: Family,
    /// One entry per tier the program is built for, in [`TIERS`] order.
    tiers: Vec<(&'static str, Emit)>,
    /// The `CsilInstr` variants, and `CallPure:<PureFunc>` entries, the
    /// program contains.
    instructions: BTreeSet<String>,
}

fn variant_name(debug: &str) -> &str {
    let end = debug
        .find(|c: char| !c.is_ascii_alphanumeric())
        .unwrap_or(debug.len());
    &debug[..end]
}

fn instructions(program: &CsilProgram) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    for instr in program.functions.iter().flat_map(|f| &f.code) {
        let debug = format!("{instr:?}");
        out.insert(variant_name(&debug).to_owned());
        if let CsilInstr::CallPure { func, .. } = instr {
            out.insert(format!("CallPure:{}", variant_name(&format!("{func:?}"))));
        }
    }
    out
}

fn chart(program: &CsilProgram, cache: &mut BodyCache) -> Emit {
    match compile_program_to_wasm(program) {
        Ok(module) => Emit::Module {
            how: match module.layout.execution_mode {
                ExecutionMode::Native => "native".to_owned(),
                ExecutionMode::InterpreterHosted => format!(
                    "hosted:{}",
                    pinewasm_aot::compile_program(program)
                        .expect_err("a hosted module means native lowering refused")
                        .kind()
                ),
            },
            module: fingerprint(&module.wasm, cache),
        },
        Err(error) => Emit::Refused(format!("refused:{}", error.kind())),
    }
}

fn standalone(
    program: &CsilProgram,
    module_type: StandaloneWasmModuleType,
    signal_plot: Option<usize>,
    cache: &mut BodyCache,
) -> Emit {
    match compile_standalone_wasm_program(
        program,
        &StandaloneWasmOptions {
            signal_plot,
            module_type,
        },
    ) {
        Ok(wasm) => Emit::Module {
            how: "ok".to_owned(),
            module: fingerprint(&wasm, cache),
        },
        Err(error) => Emit::Refused(format!("refused:{}", error.kind())),
    }
}

/// Build one program in every tier. `None` when the front end rejects it: it
/// is then not one of the gate's programs.
fn measure(program: &Program, cache: &mut BodyCache) -> Option<Record> {
    let options = match program.family {
        Family::Fixture => CompileOptions::default(),
        Family::Matrix => CompileOptions::all(),
    };
    let result = compile(&program.source, options);
    if result
        .diagnostics
        .iter()
        .any(pinewasm_span::Diagnostic::is_error)
    {
        return None;
    }
    let csil = result.program?;
    let signal_plot = match program.family {
        Family::Fixture => None,
        Family::Matrix => Some(
            csil.plots
                .iter()
                .position(|plot| plot.title.as_deref() == Some(matrix::SIGNAL_TITLE))
                .unwrap_or_else(|| panic!("{}: no designated plot", program.id)),
        ),
    };
    let mut tiers = vec![
        ("chart", chart(&csil, cache)),
        (
            "strategy",
            standalone(
                &csil,
                StandaloneWasmModuleType::Strategy,
                signal_plot,
                cache,
            ),
        ),
    ];
    if csil.metadata.strategy.is_none() {
        // An indicator-type module designates no signal plot.
        tiers.push((
            "indicator",
            standalone(&csil, StandaloneWasmModuleType::Indicator, None, cache),
        ));
    }
    Some(Record {
        id: program.id.clone(),
        family: program.family,
        tiers,
        instructions: instructions(&csil),
    })
}

/// Every program's record, in program order. The programs are independent,
/// so they are split across threads; the result does not depend on the split.
fn measure_all(programs: &[Program]) -> Vec<Record> {
    let workers = std::thread::available_parallelism()
        .map_or(1, std::num::NonZero::get)
        .min(8);
    let mut records: Vec<Option<Option<Record>>> = Vec::new();
    records.resize_with(programs.len(), || None);
    std::thread::scope(|scope| {
        let handles: Vec<_> = (0..workers)
            .map(|worker| {
                scope.spawn(move || {
                    let mut cache = BodyCache::new();
                    programs
                        .iter()
                        .enumerate()
                        .skip(worker)
                        .step_by(workers)
                        .map(|(index, program)| (index, measure(program, &mut cache)))
                        .collect::<Vec<_>>()
                })
            })
            .collect();
        for handle in handles {
            for (index, record) in handle.join().expect("worker") {
                records[index] = Some(record);
            }
        }
    });
    records
        .into_iter()
        .filter_map(|record| record.expect("every program measured"))
        .collect()
}

// ---------------------------------------------------------------------------
// The manifest.

/// Hex digits kept of a matrix cell's two hashes.
const MATRIX_HASH_DIGITS: usize = 12;
/// Hex digits kept of a fixture's per-function hashes. A pinned hash is only
/// ever compared with the new hash of the same function, so a prefix is
/// enough to see a change.
const FUNCTION_HASH_DIGITS: usize = 16;

/// One pinned (program, tier) line.
#[derive(Debug, Clone, PartialEq, Eq)]
struct Entry {
    state: String,
    /// `(module hash, function count, function digest)`, as written; absent
    /// for a refusal.
    module: Option<(String, usize, String)>,
    /// Per-function `(length, hash)`; fixtures only.
    functions: Option<Vec<(usize, String)>>,
}

/// A manifest in memory: program id, then tier, in file order.
type Manifest = Vec<(String, Vec<(String, Entry)>)>;

fn entry(family: Family, emit: &Emit) -> Entry {
    match emit {
        Emit::Refused(state) => Entry {
            state: state.clone(),
            module: None,
            functions: None,
        },
        Emit::Module { how, module } => {
            let digits = match family {
                Family::Fixture => 64,
                Family::Matrix => MATRIX_HASH_DIGITS,
            };
            Entry {
                state: how.clone(),
                module: Some((
                    hex(&module.hash)[..digits].to_owned(),
                    module.bodies.len(),
                    hex(&module.bodies_digest())[..digits].to_owned(),
                )),
                functions: (family == Family::Fixture).then(|| {
                    module
                        .bodies
                        .iter()
                        .map(|body| {
                            (
                                body.length,
                                hex(&body.hash)[..FUNCTION_HASH_DIGITS].to_owned(),
                            )
                        })
                        .collect()
                }),
            }
        }
    }
}

fn manifest_of(records: &[Record]) -> Manifest {
    records
        .iter()
        .map(|record| {
            (
                record.id.clone(),
                record
                    .tiers
                    .iter()
                    .map(|(tier, emit)| ((*tier).to_owned(), entry(record.family, emit)))
                    .collect(),
            )
        })
        .collect()
}

const MANIFEST_HEADER: &str = "\
# [modules] A program line is `P<TAB><program id>`. Each tier line under it is
#   <tier><TAB><state>[<TAB><module sha256><TAB><function count><TAB><function digest>]
# with the hashes present when a module was produced. Matrix hashes are the first 48 bits.
# [functions] Fixtures only. A module line is `F<TAB><program id><TAB><tier>`. Each line under
# it is one function body, in code-section order: <index><TAB><length><TAB><first 64 bits of its sha256>.
";

fn render_manifest(manifest: &Manifest) -> String {
    let mut out = String::from(MANIFEST_HEADER);
    out.push_str("[modules]\n");
    for (id, tiers) in manifest {
        let _ = writeln!(out, "P\t{id}");
        for (tier, entry) in tiers {
            match &entry.module {
                Some((hash, count, digest)) => {
                    let _ = writeln!(out, "{tier}\t{}\t{hash}\t{count}\t{digest}", entry.state);
                }
                None => {
                    let _ = writeln!(out, "{tier}\t{}", entry.state);
                }
            }
        }
    }
    out.push_str("[functions]\n");
    for (id, tiers) in manifest {
        for (tier, entry) in tiers {
            let Some(functions) = &entry.functions else {
                continue;
            };
            let _ = writeln!(out, "F\t{id}\t{tier}");
            for (index, (length, hash)) in functions.iter().enumerate() {
                let _ = writeln!(out, "{index}\t{length}\t{hash}");
            }
        }
    }
    out
}

fn parse_manifest(text: &str) -> Manifest {
    let malformed = |line: &str| -> ! { panic!("malformed manifest line: {line:?}") };
    let mut manifest: Manifest = Vec::new();
    let mut in_functions = false;
    // The (program, tier) the function lines being read belong to.
    let mut target: Option<(usize, usize)> = None;
    for line in text.lines().filter(|line| !line.starts_with('#')) {
        let fields: Vec<&str> = line.split('\t').collect();
        match (in_functions, fields.as_slice()) {
            (_, ["[modules]"]) => in_functions = false,
            (_, ["[functions]"]) => in_functions = true,
            (false, ["P", id]) => manifest.push(((*id).to_owned(), Vec::new())),
            (false, [tier, state]) => {
                let Some((_, tiers)) = manifest.last_mut() else {
                    malformed(line)
                };
                tiers.push((
                    (*tier).to_owned(),
                    Entry {
                        state: (*state).to_owned(),
                        module: None,
                        functions: None,
                    },
                ));
            }
            (false, [tier, state, hash, count, digest]) => {
                let Some((_, tiers)) = manifest.last_mut() else {
                    malformed(line)
                };
                let Ok(count) = count.parse() else {
                    malformed(line)
                };
                tiers.push((
                    (*tier).to_owned(),
                    Entry {
                        state: (*state).to_owned(),
                        module: Some(((*hash).to_owned(), count, (*digest).to_owned())),
                        functions: None,
                    },
                ));
            }
            (true, ["F", id, tier]) => {
                let found = manifest.iter().position(|(p, _)| p == id).and_then(|p| {
                    let t = manifest[p].1.iter().position(|(name, _)| name == tier)?;
                    Some((p, t))
                });
                let Some((p, t)) = found else { malformed(line) };
                manifest[p].1[t].1.functions = Some(Vec::new());
                target = Some((p, t));
            }
            (true, [index, length, hash]) => {
                let (Some((p, t)), Ok(index), Ok(length)) =
                    (target, index.parse::<usize>(), length.parse::<usize>())
                else {
                    malformed(line)
                };
                let functions = manifest[p].1[t]
                    .1
                    .functions
                    .as_mut()
                    .expect("set by the F line");
                if index != functions.len() {
                    malformed(line);
                }
                functions.push((length, (*hash).to_owned()));
            }
            _ => malformed(line),
        }
    }
    manifest
}

// ---------------------------------------------------------------------------
// The comparison.

/// How a measured manifest differs from the pinned one.
#[derive(Debug, Default, PartialEq, Eq)]
struct Difference {
    /// A module was pinned and a module is produced, reached the same way,
    /// and its bytes differ.
    bytes_changed: Vec<String>,
    /// A tier that produced a module now refuses, or the reverse, or the way
    /// it is reached (native, hosted, refusal kind) changed.
    acceptance: Vec<String>,
    /// A program or tier added to or removed from the set, or reordered.
    membership: Vec<String>,
}

fn describe_bytes(was: &Entry, now: &Entry) -> String {
    let (Some((was_hash, was_count, was_digest)), Some((now_hash, now_count, now_digest))) =
        (&was.module, &now.module)
    else {
        unreachable!("both entries are modules");
    };
    if was_digest == now_digest && was_count == now_count {
        return format!(
            "module {was_hash} -> {now_hash}; every function body is unchanged, so the change \
             is outside the code section"
        );
    }
    let mut text = format!("module {was_hash} -> {now_hash}");
    if was_count != now_count {
        let _ = write!(text, "; {was_count} -> {now_count} function bodies");
    }
    match (&was.functions, &now.functions) {
        (Some(was), Some(now)) => {
            let changed: Vec<String> = was
                .iter()
                .zip(now)
                .enumerate()
                .filter(|(_, (was, now))| was != now)
                .map(|(index, (was, now))| {
                    format!(
                        "function {index} ({} -> {} bytes, {} -> {})",
                        was.0,
                        now.0,
                        &was.1[..12],
                        &now.1[..12]
                    )
                })
                .collect();
            let _ = write!(text, "; changed: {}", changed.join(", "));
        }
        _ => text.push_str(
            "; function bodies changed (per-function hashes are pinned for fixtures only)",
        ),
    }
    text
}

fn compare(pinned: &Manifest, measured: &Manifest) -> Difference {
    type Flat<'a> = BTreeMap<(&'a str, &'a str), &'a Entry>;
    fn flatten(manifest: &Manifest) -> Flat<'_> {
        manifest
            .iter()
            .flat_map(|(id, tiers)| {
                tiers
                    .iter()
                    .map(move |(tier, entry)| ((id.as_str(), tier.as_str()), entry))
            })
            .collect()
    }
    let (was, now) = (flatten(pinned), flatten(measured));
    let mut difference = Difference::default();
    for (id, tiers) in measured {
        for (tier, entry) in tiers {
            let Some(pinned) = was.get(&(id.as_str(), tier.as_str())) else {
                difference.membership.push(format!(
                    "{id} [{tier}]: not in the manifest, now {}",
                    entry.state
                ));
                continue;
            };
            if pinned.state != entry.state {
                let label = match (pinned.module.is_some(), entry.module.is_some()) {
                    (false, true) => "newly accepted",
                    (true, false) => "newly refused",
                    (true, true) => "built another way",
                    (false, false) => "refused for another reason",
                };
                difference.acceptance.push(format!(
                    "{id} [{tier}]: {label}: was {}, now {}",
                    pinned.state, entry.state
                ));
            } else if *pinned != entry {
                difference.bytes_changed.push(format!(
                    "{id} [{tier}]: bytes changed: {}",
                    describe_bytes(pinned, entry)
                ));
            }
        }
    }
    for (id, tiers) in pinned {
        for (tier, entry) in tiers {
            if !now.contains_key(&(id.as_str(), tier.as_str())) {
                difference.membership.push(format!(
                    "{id} [{tier}]: was {}, no longer built",
                    entry.state
                ));
            }
        }
    }
    if difference == Difference::default() && pinned != measured {
        difference
            .membership
            .push("the program order changed".to_owned());
    }
    difference
}

// ---------------------------------------------------------------------------
// The inventory.

/// The variant names of `pub enum <name>` in a Rust source file: the
/// identifiers that open a line at one level of indentation inside the enum.
fn enum_variants(source: &str, name: &str) -> Vec<String> {
    let opening = format!("pub enum {name} {{\n");
    let start = source
        .find(&opening)
        .unwrap_or_else(|| panic!("no `pub enum {name}`"))
        + opening.len();
    let body = &source[start..start + source[start..].find("\n}").expect("the enum closes")];
    body.lines()
        .filter_map(|line| {
            let rest = line.strip_prefix("    ")?;
            rest.starts_with(|c: char| c.is_ascii_uppercase())
                .then(|| variant_name(rest).to_owned())
        })
        .collect()
}

fn csil_instr_variants() -> Vec<String> {
    enum_variants(include_str!("../../pinewasm_csil/src/lib.rs"), "CsilInstr")
}

fn pure_func_variants() -> Vec<String> {
    enum_variants(
        include_str!("../../pinewasm_hir/src/builtins.rs"),
        "PureFunc",
    )
}

/// The inventory text: per variant, the number of fixtures and of matrix
/// cells with at least one natively lowered module that contain it.
fn render_inventory(records: &[Record]) -> String {
    let native: Vec<&Record> = records
        .iter()
        .filter(|record| record.tiers.iter().any(|(_, emit)| emit.is_native()))
        .collect();
    let count = |family: Family, key: &str| {
        native
            .iter()
            .filter(|record| record.family == family && record.instructions.contains(key))
            .count()
    };
    let family_total = |family: Family, records: &mut dyn Iterator<Item = &Record>| {
        records.filter(|record| record.family == family).count()
    };
    let instrs = csil_instr_variants();
    let pures = pure_func_variants();
    let known: BTreeSet<String> = instrs
        .iter()
        .cloned()
        .chain(pures.iter().map(|pure| format!("CallPure:{pure}")))
        .collect();
    for record in records {
        for key in &record.instructions {
            assert!(
                known.contains(key),
                "{}: {key} is not a variant this test read from the enum definitions",
                record.id
            );
        }
    }

    let mut out = String::new();
    let _ = writeln!(
        out,
        "# Programs with at least one natively lowered module (a `native` chart module or a\n\
         # standalone module): {} of {} fixtures, {} of {} matrix cells.\n\
         # Columns: <variant><TAB><fixtures containing it><TAB><matrix cells containing it>.",
        family_total(Family::Fixture, &mut native.iter().copied()),
        family_total(Family::Fixture, &mut records.iter()),
        family_total(Family::Matrix, &mut native.iter().copied()),
        family_total(Family::Matrix, &mut records.iter()),
    );
    let mut section = |title: &str, keys: Vec<(String, String)>| {
        let rows: Vec<(String, usize, usize)> = keys
            .into_iter()
            .map(|(label, key)| {
                (
                    label,
                    count(Family::Fixture, &key),
                    count(Family::Matrix, &key),
                )
            })
            .collect();
        let exercised = rows.iter().filter(|row| row.1 + row.2 > 0).count();
        let _ = writeln!(
            out,
            "[{title}] {} variants, {exercised} exercised, {} never exercised",
            rows.len(),
            rows.len() - exercised
        );
        for (label, fixtures, cells) in &rows {
            let _ = writeln!(out, "{label}\t{fixtures}\t{cells}");
        }
        let never: Vec<&str> = rows
            .iter()
            .filter(|row| row.1 + row.2 == 0)
            .map(|row| row.0.as_str())
            .collect();
        let _ = writeln!(out, "[{title} never exercised] {}", never.join(" "));
    };
    section(
        "CsilInstr",
        instrs.iter().map(|v| (v.clone(), v.clone())).collect(),
    );
    section(
        "PureFunc",
        pures
            .iter()
            .map(|v| (v.clone(), format!("CallPure:{v}")))
            .collect(),
    );
    out
}

// ---------------------------------------------------------------------------
// The pinned file.

fn manifest_path() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/emitter_byte_gate/manifest.rs")
}

/// The Rust source file that holds the manifest and the inventory.
fn render_source(manifest: &str, inventory: &str) -> String {
    for text in [manifest, inventory] {
        assert!(!text.contains('"'), "an id would end the raw string");
    }
    format!(
        "//! The pinned emitter byte manifest and instruction inventory. Generated by\n\
         //! `tests/emitter_byte_gate.rs`; do not edit by hand. Rewrite with:\n\
         //! `EMITTER_BYTE_GATE_BLESS=1 cargo test -p pinewasm_aot --test emitter_byte_gate`\n\n\
         pub const INVENTORY: &str = r\"{inventory}\";\n\n\
         pub const PINNED: &str = r\"{manifest}\";\n"
    )
}

/// One measurement of the whole set, shared by the tests of this file.
fn first_measurement() -> &'static Vec<Record> {
    static FIRST: OnceLock<Vec<Record>> = OnceLock::new();
    FIRST.get_or_init(|| measure_all(&programs()))
}

fn line_differences(was: &str, now: &str) -> String {
    let (was, now): (BTreeSet<&str>, BTreeSet<&str>) =
        (was.lines().collect(), now.lines().collect());
    let mut out = String::new();
    for line in was.difference(&now) {
        let _ = writeln!(out, "- {line}");
    }
    for line in now.difference(&was) {
        let _ = writeln!(out, "+ {line}");
    }
    out
}

// ---------------------------------------------------------------------------
// The tests.

#[test]
fn emitted_bytes_match_the_pinned_manifest() {
    let started = std::time::Instant::now();
    let records = first_measurement();
    let mut ids = BTreeSet::new();
    for record in records {
        assert!(ids.insert(record.id.as_str()), "duplicate id {}", record.id);
    }
    let measured = manifest_of(records);
    let rendered = render_manifest(&measured);
    let inventory = render_inventory(records);
    assert_eq!(
        parse_manifest(&rendered),
        measured,
        "the manifest does not round-trip"
    );

    for family in [Family::Fixture, Family::Matrix] {
        let of_family: Vec<&Record> = records.iter().filter(|r| r.family == family).collect();
        println!(
            "[emitter-byte-gate] {family:?}: {} programs",
            of_family.len()
        );
        for tier in TIERS {
            let mut states: BTreeMap<String, usize> = BTreeMap::new();
            for (_, emit) in of_family
                .iter()
                .flat_map(|record| &record.tiers)
                .filter(|(name, _)| *name == tier)
            {
                *states.entry(emit.state().to_owned()).or_default() += 1;
            }
            println!("[emitter-byte-gate]   {tier:<9} {states:?}");
        }
    }
    for line in inventory.lines().filter(|line| line.starts_with('[')) {
        println!("[emitter-byte-gate] {line}");
    }
    println!(
        "[emitter-byte-gate] measured in {:.1}s",
        started.elapsed().as_secs_f64()
    );

    let path = manifest_path();
    let source = render_source(&rendered, &inventory);
    if std::env::var_os("EMITTER_BYTE_GATE_BLESS").is_some() {
        std::fs::write(&path, &source)
            .unwrap_or_else(|error| panic!("write {}: {error}", path.display()));
        println!(
            "[emitter-byte-gate] rewrote {} ({} bytes)",
            path.display(),
            source.len()
        );
        return;
    }

    let difference = compare(&parse_manifest(manifest::PINNED), &measured);
    let mut report = String::new();
    for (title, lines) in [
        (
            "BYTES CHANGED: the backend emits other bytes for a module it built before",
            &difference.bytes_changed,
        ),
        (
            "NEWLY ACCEPTED OR REFUSED: a tier's answer for a program changed",
            &difference.acceptance,
        ),
        (
            "PROGRAM SET CHANGED: a program or tier was added or removed",
            &difference.membership,
        ),
    ] {
        if !lines.is_empty() {
            let _ = writeln!(report, "{title} ({}):\n{}\n", lines.len(), lines.join("\n"));
        }
    }
    assert!(
        report.is_empty(),
        "the emitter byte gate differs from the pinned manifest. Review each difference; if \
         every one is intended, rewrite the manifest with EMITTER_BYTE_GATE_BLESS=1.\n\n{report}"
    );
    assert!(
        inventory == manifest::INVENTORY,
        "the instruction inventory changed; review it, then rewrite the manifest with \
         EMITTER_BYTE_GATE_BLESS=1.\n{}",
        line_differences(manifest::INVENTORY, &inventory)
    );
    assert!(
        std::fs::read_to_string(&path).ok().as_deref() == Some(source.as_str()),
        "{} is not what the gate writes (header out of date); rewrite it with \
         EMITTER_BYTE_GATE_BLESS=1",
        path.display()
    );
}

/// The gate is a function of the sources alone: a second measurement of every
/// program, on fresh threads with empty caches, renders the same manifest and
/// the same inventory.
#[test]
fn the_gate_is_deterministic() {
    let first = first_measurement();
    let second = measure_all(&programs());
    assert!(
        render_manifest(&manifest_of(first)) == render_manifest(&manifest_of(&second)),
        "two measurements of the same programs differ:\n{:#?}",
        compare(&manifest_of(first), &manifest_of(&second))
    );
    assert_eq!(render_inventory(first), render_inventory(&second));
}

fn sample_module() -> Vec<u8> {
    let result = compile(
        "//@version=6\nindicator(\"sample\")\nplot(ta.ema(close, 14) > close ? 1 : -1)\n",
        CompileOptions::default(),
    );
    compile_program_to_wasm(&result.program.expect("the sample compiles"))
        .expect("the sample builds")
        .wasm
}

fn sample_manifest(family: Family, emit: Emit) -> Manifest {
    vec![(
        "sample".to_owned(),
        vec![("chart".to_owned(), entry(family, &emit))],
    )]
}

fn native(wasm: &[u8]) -> Emit {
    Emit::Module {
        how: "native".to_owned(),
        module: fingerprint(wasm, &mut BodyCache::new()),
    }
}

/// The detector's check: one changed byte inside one function body is
/// reported as "bytes changed", for that function index and no other, and is
/// not reported as an acceptance change.
#[test]
fn one_changed_byte_in_a_function_body_is_reported_for_that_function() {
    let wasm = sample_module();
    let ranges = body_ranges(&wasm);
    assert!(ranges.len() > 3, "the sample has several function bodies");

    for target in [0, 2, ranges.len() - 1] {
        let mut planted = wasm.clone();
        // The byte before the body's closing `end`: inside the body, and
        // changing it moves no section or body boundary.
        let at = ranges[target].end - 2;
        planted[at] ^= 0x01;

        let pinned = sample_manifest(Family::Fixture, native(&wasm));
        let measured = sample_manifest(Family::Fixture, native(&planted));
        let difference = compare(&pinned, &measured);
        assert!(difference.acceptance.is_empty(), "{difference:?}");
        assert!(difference.membership.is_empty(), "{difference:?}");
        let [line] = difference.bytes_changed.as_slice() else {
            panic!("expected one line, got {difference:?}");
        };
        assert!(
            line.starts_with("sample [chart]: bytes changed: module "),
            "{line}"
        );
        let named: Vec<&str> = line
            .match_indices("function ")
            .map(|(at, _)| {
                let rest = &line[at + "function ".len()..];
                &rest[..rest.find(' ').expect("a space after the index")]
            })
            .collect();
        assert_eq!(named, [target.to_string()], "{line}");

        // A matrix cell pins no per-function hashes: the same change is still
        // "bytes changed", in the code section.
        let difference = compare(
            &sample_manifest(Family::Matrix, native(&wasm)),
            &sample_manifest(Family::Matrix, native(&planted)),
        );
        let [line] = difference.bytes_changed.as_slice() else {
            panic!("expected one line, got {difference:?}");
        };
        assert!(line.contains("function bodies changed"), "{line}");
    }

    // A changed byte outside the code section is "bytes changed" too, and
    // says that no function body moved.
    let mut planted = wasm.clone();
    planted.extend_from_slice(&[0x00, 0x02, 0x01, b'x']);
    let difference = compare(
        &sample_manifest(Family::Fixture, native(&wasm)),
        &sample_manifest(Family::Fixture, native(&planted)),
    );
    let [line] = difference.bytes_changed.as_slice() else {
        panic!("expected one line, got {difference:?}");
    };
    assert!(line.contains("outside the code section"), "{line}");
}

/// The comparison's own check: a change of answer is an acceptance change
/// and never "bytes changed"; a program that comes or goes is neither.
#[test]
fn a_changed_answer_is_reported_as_newly_accepted_or_refused() {
    let wasm = sample_module();
    let refused = || Emit::Refused("refused:UnsupportedIntegerNaEncoding".to_owned());
    let hosted = || Emit::Module {
        how: "hosted:UnsupportedIntegerNaEncoding".to_owned(),
        module: fingerprint(&wasm, &mut BodyCache::new()),
    };
    let one = |id: &str, emit: Emit| {
        (
            id.to_owned(),
            vec![("chart".to_owned(), entry(Family::Fixture, &emit))],
        )
    };

    let pinned: Manifest = vec![
        one("a", native(&wasm)),
        one("b", refused()),
        one("c", hosted()),
        one("d", refused()),
        one("same", native(&wasm)),
        one("gone", native(&wasm)),
    ];
    assert_eq!(compare(&pinned, &pinned), Difference::default());

    let measured: Manifest = vec![
        one("a", refused()),
        one("b", native(&wasm)),
        one("c", native(&wasm)),
        one("d", Emit::Refused("refused:UnsupportedOpcode".to_owned())),
        one("same", native(&wasm)),
        one("new", native(&wasm)),
    ];
    let difference = compare(&pinned, &measured);
    assert!(difference.bytes_changed.is_empty(), "{difference:?}");
    assert_eq!(
        difference.acceptance,
        [
            "a [chart]: newly refused: was native, now refused:UnsupportedIntegerNaEncoding",
            "b [chart]: newly accepted: was refused:UnsupportedIntegerNaEncoding, now native",
            "c [chart]: built another way: was hosted:UnsupportedIntegerNaEncoding, now native",
            "d [chart]: refused for another reason: was refused:UnsupportedIntegerNaEncoding, \
             now refused:UnsupportedOpcode",
        ]
    );
    assert_eq!(
        difference.membership,
        [
            "new [chart]: not in the manifest, now native",
            "gone [chart]: was native, no longer built",
        ]
    );

    let reordered = compare(
        &vec![one("a", refused()), one("b", refused())],
        &vec![one("b", refused()), one("a", refused())],
    );
    assert_eq!(reordered.membership, ["the program order changed"]);
}

/// The variant lists the inventory is built on are the enums' own: every
/// variant the reader finds is one, and it finds the ones named here.
#[test]
fn the_inventory_reads_the_variant_lists_from_the_enum_definitions() {
    let instrs = csil_instr_variants();
    let pures = pure_func_variants();
    for expected in ["PushNa", "CallPure", "Return"] {
        assert!(
            instrs.iter().any(|v| v == expected),
            "CsilInstr::{expected}"
        );
    }
    for expected in ["Na", "Nz", "MathAbs"] {
        assert!(pures.iter().any(|v| v == expected), "PureFunc::{expected}");
    }
    for list in [&instrs, &pures] {
        let distinct: BTreeSet<&String> = list.iter().collect();
        assert_eq!(distinct.len(), list.len(), "a variant was read twice");
    }
    assert_eq!(variant_name("CallPure { func: Na, argc: 1 }"), "CallPure");
    assert_eq!(variant_name("PushI64(3)"), "PushI64");
    assert_eq!(variant_name("PushNa"), "PushNa");
}
